solution:
.bento {
  width: 100%;
  max-width: 624px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: 100px;
  gap: 12px;
}

.box {
  background: #1e293b;
  color: #f8fafc;
  padding: 16px;
  border-radius: 12px;
  font-weight: 600;
}

.bento-main {
  background: #0284c7;
  grid-column: span 2;
  grid-row: span 2;
}

@media (max-width: 600px) {
  .bento {
    grid-template-columns: 1fr;
  }
  .bento-main {
    grid-column: span 1;
    grid-row: span 1;
  }
}
